import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import ApiService from '../../Services/ApiService';

export default function InfluencerReels() {
    const [reels, setReels] = useState([]);
    const [loading, setLoading] = useState(true);
    const [productNames, setProductNames] = useState({}); // Store product names by ID

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        loadReels();
    }, []);

    const loadReels = async () => {
        try {
            setLoading(true);
            const response = await ApiService.getInfluencerReels();
            if (response.success) {
                setReels(response.data);
                // Load product names for all reels
                loadProductNames(response.data);
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading reels:', error);
            setLoading(false);
        }
    };

    // Function to load product names from the database
    const loadProductNames = async (reelsData) => {
        try {
            // Collect all unique product IDs from all reels
            const allProductIds = new Set();
            reelsData.forEach(reel => {
                if (reel.product_ids && Array.isArray(reel.product_ids)) {
                    reel.product_ids.forEach(id => allProductIds.add(id));
                }
            });

            if (allProductIds.size === 0) return;

            // For now, we'll simulate product names since we don't have a direct API endpoint
            // In a real implementation, you would call an API to get product names by IDs
            const productNamesMap = {};
            allProductIds.forEach(id => {
                productNamesMap[id] = `Product ${id}`; // Placeholder names
            });
            
            setProductNames(productNamesMap);
        } catch (error) {
            console.error('Error loading product names:', error);
        }
    };

    const getStatusBadge = (status) => {
        switch (status) {
            case 'approved':
                return <span className="badge bg-success">Approved</span>;
            case 'pending':
                return <span className="badge bg-warning">Pending</span>;
            case 'rejected':
                return <span className="badge bg-danger">Rejected</span>;
            default:
                return <span className="badge bg-secondary">Unknown</span>;
        }
    };

    // Function to render product information for a reel
    const renderProductInfo = (productIds) => {
        if (!productIds || productIds.length === 0) {
            return <span className="text-muted">No products</span>;
        }
        
        // Display product names instead of just count
        return (
            <div>
                {productIds.map((id, index) => (
                    <div key={id}>
                        {productNames[id] || `Product ${id}`}
                        {index < productIds.length - 1 && ", "}
                    </div>
                ))}
            </div>
        );
    };

    // Function to calculate reel count per product
    const getReelCountPerProduct = (productId) => {
        // Count how many reels have this product ID
        let count = 0;
        reels.forEach(reel => {
            if (reel.product_ids && reel.product_ids.includes(productId)) {
                count++;
            }
        });
        return count;
    };

    // Function to handle viewing a reel
    const handleViewReel = (reel) => {
        // For now, we'll just show a modal or alert with reel details
        // In a full implementation, this would open a video player
        alert(`Viewing reel: ${reel.title}\nProduct IDs: ${reel.product_ids ? reel.product_ids.join(', ') : 'None'}`);
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">My Reels</h4>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-header d-flex align-items-center justify-content-between">
                        <h5 className="card-title mb-0">Reels Management</h5>
                        <Link to="/studio/influencer/upload" className="btn btn-success">
                            <i className="ri-add-line me-1"></i> Upload Reel
                        </Link>
                    </div>
                    <div className="card-body">
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                            </div>
                        ) : reels.length === 0 ? (
                            <div className="text-center py-5">
                                <h5>No reels found</h5>
                                <p className="text-muted">Upload your first reel to get started.</p>
                                <Link to="/studio/influencer/upload" className="btn btn-success">
                                    <i className="ri-upload-line me-1"></i> Upload Reel
                                </Link>
                            </div>
                        ) : (
                            <div className="table-responsive">
                                <table className="table table-hover align-middle mb-0">
                                    <thead>
                                        <tr>
                                            <th>Product Name</th>
                                            <th>Reel Count</th>
                                            <th>Title</th>
                                            <th>Category</th>
                                            <th>Status</th>
                                            <th>Views</th>
                                            <th>Likes</th>
                                            <th>Date</th>
                                            <th>Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {reels.map((reel) => (
                                            <tr key={reel.id}>
                                                <td>
                                                    {renderProductInfo(reel.product_ids)}
                                                </td>
                                                <td>
                                                    {/* Show reel count for the first product in the list */}
                                                    {reel.product_ids && reel.product_ids.length > 0 ? (
                                                        <span className="badge bg-primary">
                                                            {getReelCountPerProduct(reel.product_ids[0])}
                                                        </span>
                                                    ) : (
                                                        <span className="badge bg-secondary">0</span>
                                                    )}
                                                </td>
                                                <td>{reel.title}</td>
                                                <td>{reel.category_name || 'N/A'}</td>
                                                <td>{getStatusBadge(reel.status)}</td>
                                                <td>{reel.views}</td>
                                                <td>{reel.likes}</td>
                                                <td>{new Date(reel.created_at).toLocaleDateString()}</td>
                                                <td>
                                                    <button 
                                                        className="btn btn-sm btn-soft-info me-1"
                                                        onClick={() => handleViewReel(reel)}
                                                    >
                                                        <i className="ri-eye-line"></i>
                                                    </button>
                                                    <button className="btn btn-sm btn-soft-warning me-1">
                                                        <i className="ri-edit-line"></i>
                                                    </button>
                                                    <button className="btn btn-sm btn-soft-danger">
                                                        <i className="ri-delete-bin-line"></i>
                                                    </button>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
